"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { ChevronUp, ChevronDown, Edit, Trash2, AlertCircle, Loader2, Package, RefreshCw, Search, X, Download } from 'lucide-react';
import Layout from "../../Layout";
import * as XLSX from "xlsx";

export default function ManageProducts() {
  const navigate = useNavigate();
  const [products, setProducts] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [sortDirection, setSortDirection] = useState("asc");
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedZone, setSelectedZone] = useState("");
  const [selectedYear, setSelectedYear] = useState("");
  const [zones, setZones] = useState([]);
  const [selectedProduct, setSelectedProduct] = useState(null);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    try {
      const [productsRes, zonesRes] = await Promise.all([
        axios.get(`${process.env.REACT_APP_API_URL}/api/products`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${process.env.REACT_APP_API_URL}/api/zones`, { headers: { Authorization: `Bearer ${token}` } }),
      ]);
      setProducts(productsRes.data);
      setZones(zonesRes.data);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de la récupération des données");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSort = () => {
    setSortDirection(sortDirection === "asc" ? "desc" : "asc");
  };

  const getSortIcon = () => {
    return sortDirection === "asc" ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />;
  };

  const handleDeleteProduct = async (id) => {
    if (window.confirm("Êtes-vous sûr de vouloir supprimer ce produit ?")) {
      try {
        const token = localStorage.getItem("token");
        await axios.delete(`${process.env.REACT_APP_API_URL}/api/products/${id}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        setProducts(products.filter((p) => p._id !== id));
      } catch (err) {
        setError(err.response?.data?.message || "Erreur lors de la suppression");
      }
    }
  };

  const exportToExcel = () => {
    const data = products.map((product) => ({
      "Numéro de Bielle": product.numeroBielle || "N/A",
      Nom: product.nameProduct,
      "Prix Unitaire (DH)": product.priceForOne.toFixed(2),
      Quantité: product.quantity,
      Zone: product.zoneId?.zoneName || "N/A",
      "Montant (DH)": product.amount.toFixed(2),
      Unité: product.unity === "unit" ? "unité" : product.unity,
      "Seuil de Sécurité": product.safetyThreshold || "N/A",
      "Date d'Expiration": new Date(product.expirationDate).toLocaleDateString('fr-FR'),
      Fournisseurs: product.nameSupplier?.length > 0 ? product.nameSupplier.join(", ") : "N/A",
      Bons: product.bons?.length > 0
        ? product.bons.map((bon) => `${bon.type} (${new Date(bon.DateBon).toLocaleDateString('fr-FR')}${bon.supplier ? ` - ${bon.supplier}` : ""})`).join("; ")
        : "N/A",
    }));

    const worksheet = XLSX.utils.json_to_sheet(data);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Produits");

    // Auto-size columns
    const colWidths = Object.keys(data[0]).map((key, i) => ({
      wch: Math.max(
        key.length,
        ...data.map(row => String(row[key]).length)
      )
    }));
    worksheet['!cols'] = colWidths;

    XLSX.writeFile(workbook, `Produits_${new Date().toLocaleDateString('fr-FR').replace(/\//g, '-')}.xlsx`);
  };

  const filteredProducts = products.filter((product) => {
    const searchLower = searchTerm.toLowerCase();
    const nameMatch = product.nameProduct.toLowerCase().includes(searchLower);
    const supplierMatch = product.nameSupplier?.some((supplier) => supplier.toLowerCase().includes(searchLower)) || false;
    const zoneMatch = product.zoneId?.zoneName?.toLowerCase().includes(searchLower) || false;
    const numeroBielleMatch = product.numeroBielle?.toLowerCase().includes(searchLower) || false;
    return (nameMatch || supplierMatch || zoneMatch || numeroBielleMatch) &&
           (selectedZone ? product.zoneId?._id === selectedZone : true) &&
           (selectedYear ? new Date(product.expirationDate).getFullYear().toString() === selectedYear : true);
  });

  const sortedProducts = [...filteredProducts].sort((a, b) => {
    const dateA = new Date(a.expirationDate);
    const dateB = new Date(b.expirationDate);
    return sortDirection === "asc" ? dateA - dateB : dateB - dateA;
  });

  const years = Array.from(new Set(products.map((p) => new Date(p.expirationDate).getFullYear()))).sort();

  const openModal = (product) => setSelectedProduct(product);
  const closeModal = () => setSelectedProduct(null);

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div>
                <h1 className="text-2xl font-bold tracking-tight">Gestion des Produits</h1>
                <p className="text-white/80 mt-1 text-sm">Liste des produits triés par date d'expiration</p>
              </div>
              <div className="flex gap-4">
                <button
                  onClick={() => navigate("/Delivery")}
                  className="px-4 py-2.5 bg-white text-[#00717F] rounded-lg shadow-sm hover:bg-[#C8A45D/20] transition-colors duration-200 flex items-center gap-2 font-medium"
                >
                  <Package className="h-4 w-4" /> Livraison
                </button>
                <button
                  onClick={exportToExcel}
                  className="px-4 py-2.5 bg-white text-[#00717F] rounded-lg shadow-sm hover:bg-[#C8A45D/20] transition-colors duration-200 flex items-center gap-2 font-medium"
                >
                  <Download className="h-4 w-4" /> Exporter vers Excel
                </button>
              </div>
            </div>
          </div>

          {error && (
            <div className="mx-6 my-4 p-4 bg-red-50 border-l-4 border-red-500 rounded-r-lg flex items-center gap-3">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
              <p className="text-red-700 text-sm">{error}</p>
            </div>
          )}

          <div className="p-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            <div className="flex flex-col sm:flex-row gap-4 w-full sm:w-auto">
              <div className="relative w-full sm:w-64">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                <input
                  type="text"
                  placeholder="Rechercher par nom, fournisseur, zone, numéro..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2 w-full border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
                />
              </div>
              <select
                value={selectedZone}
                onChange={(e) => setSelectedZone(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
              >
                <option value="">Toutes les zones</option>
                {zones.map((zone) => (
                  <option key={zone._id} value={zone._id}>
                    {zone.zoneName}
                  </option>
                ))}
              </select>
              <select
                value={selectedYear}
                onChange={(e) => setSelectedYear(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] focus:border-transparent"
              >
                <option value="">Toutes les années</option>
                {years.map((year) => (
                  <option key={year} value={year}>
                    {year}
                  </option>
                ))}
              </select>
            </div>
            <button
              onClick={fetchData}
              className="flex items-center gap-2 text-[#00717F] hover:text-[#C8A45D] transition-colors duration-200 text-sm font-medium"
            >
              <RefreshCw className="h-4 w-4" /> Rafraîchir
            </button>
          </div>

          {isLoading ? (
            <div className="flex justify-center items-center h-64">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                <p className="text-[#00717F] text-sm font-medium">Chargement des produits...</p>
              </div>
            </div>
          ) : (
            <div className="overflow-x-auto px-4 pb-6">
              <table className="min-w-full divide-y divide-[#C8A45D/30]">
                <thead>
                  <tr className="bg-[#F5F6FA] text-[#00717F]">
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider rounded-tl-lg">Numéro de Bielle</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Nom</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Prix Unitaire</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Quantité</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Zone</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Montant</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Unité</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Seuil de Sécurité</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider cursor-pointer group" onClick={handleSort}>
                      <div className="flex items-center gap-1">
                        Date d'Expiration
                        <span className="bg-[#00717F]/10 p-1 rounded group-hover:bg-[#00717F]/20 transition-colors duration-200">
                          {getSortIcon()}
                        </span>
                      </div>
                    </th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">Fournisseurs</th>
                    <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider rounded-tr-lg">Actions</th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                  {sortedProducts.length === 0 ? (
                    <tr>
                      <td colSpan={11} className="py-8 text-center text-gray-500">
                        <Package className="h-12 w-12 mx-auto mb-2 text-gray-400" />
                        Aucun produit trouvé
                      </td>
                    </tr>
                  ) : (
                    sortedProducts.map((product) => (
                      <tr key={product._id} className="hover:bg-[#F5F6FA]/30 transition-colors duration-150 cursor-pointer" onClick={() => openModal(product)}>
                        <td className="py-4 px-4 text-sm text-gray-700">{product.numeroBielle || "N/A"}</td>
                        <td className="py-4 px-4 text-sm font-medium text-gray-900">{product.nameProduct}</td>
                        <td className="py-4 px-4 text-sm text-gray-700">{product.priceForOne.toFixed(2)} DH</td>
                        <td className="py-4 px-4 text-sm text-gray-700">{product.quantity}</td>
                        <td className="py-4 px-4 text-sm">
                          {product.zoneId?.zoneName ? (
                            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-[#C8A45D/20] text-[#00717F]">
                              {product.zoneId.zoneName}
                            </span>
                          ) : (
                            <span className="text-gray-500">N/A</span>
                          )}
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-700">{product.amount.toFixed(2)} DH</td>
                        <td className="py-4 px-4 text-sm text-gray-700">{product.unity === "unit" ? "unité" : product.unity}</td>
                        <td className="py-4 px-4 text-sm text-gray-700">{product.safetyThreshold || "N/A"}</td>
                        <td className="py-4 px-4 text-sm">
                          {new Date() > new Date(product.expirationDate) ? (
                            <span className="inline-flex items-center px-3 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800">
                              Expiré: {new Date(product.expirationDate).toLocaleDateString('fr-FR')}
                            </span>
                          ) : (
                            <span className="text-gray-700">{new Date(product.expirationDate).toLocaleDateString('fr-FR')}</span>
                          )}
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-700 whitespace-nowrap">
                          {product.nameSupplier?.length > 0 ? product.nameSupplier.join(", ") : "N/A"}
                        </td>
                        <td className="py-4 px-4 text-sm" onClick={(e) => e.stopPropagation()}>
                          <div className="flex gap-2">
                            <button onClick={() => navigate(`/EditProduct/${product._id}`)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-full" aria-label="Modifier">
                              <Edit className="h-5 w-5" />
                            </button>
                            <button onClick={() => handleDeleteProduct(product._id)} className="p-2 text-red-600 hover:bg-red-50 rounded-full" aria-label="Supprimer">
                              <Trash2 className="h-5 w-5" />
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {selectedProduct && (
          <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex justify-center items-center z-50 p-4">
            <div className="max-w-2xl w-full bg-white rounded-xl shadow-xl overflow-hidden">
              <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] border-b relative p-6">
                <button onClick={closeModal} className="absolute right-4 top-4 rounded-full p-1.5 bg-white/90 text-zinc-500 hover:text-zinc-700">
                  <X className="h-5 w-5" />
                </button>
                <h2 className="text-2xl font-bold text-white">Détails du Produit</h2>
              </div>
              <div className="p-6 space-y-6">
                <div className="grid md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <h3 className="text-sm font-medium text-zinc-500">Numéro de Bielle</h3>
                    <p className="text-lg font-medium text-zinc-900">{selectedProduct.numeroBielle || "N/A"}</p>
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-sm font-medium text-zinc-500">Nom du Produit</h3>
                    <p className="text-lg font-medium text-zinc-900">{selectedProduct.nameProduct}</p>
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-sm font-medium text-zinc-500">Prix Unitaire</h3>
                    <p className="text-lg font-medium text-zinc-900">{selectedProduct.priceForOne.toFixed(2)} DH</p>
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-sm font-medium text-zinc-500">Quantité</h3>
                    <p className="text-lg font-medium text-zinc-900">{selectedProduct.quantity} {selectedProduct.unity === "unit" ? "unité" : selectedProduct.unity}</p>
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-sm font-medium text-zinc-500">Zone</h3>
                    <p className="text-lg font-medium text-zinc-900">{selectedProduct.zoneId?.zoneName || "N/A"}</p>
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-sm font-medium text-zinc-500">Montant Total</h3>
                    <p className="text-lg font-medium text-zinc-900">{selectedProduct.amount.toFixed(2)} DH</p>
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-sm font-medium text-zinc-500">Unité</h3>
                    <p className="text-lg font-medium text-zinc-900">{selectedProduct.unity === "unit" ? "unité" : selectedProduct.unity}</p>
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-sm font-medium text-zinc-500">Seuil de Sécurité</h3>
                    <p className="text-lg font-medium text-zinc-900">{selectedProduct.safetyThreshold || "N/A"}</p>
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-sm font-medium text-zinc-500">Date d'Expiration</h3>
                    <p className="text-lg font-medium text-zinc-900">
                      {new Date() > new Date(selectedProduct.expirationDate) ? (
                        <span className="text-red-600">Expiré: {new Date(selectedProduct.expirationDate).toLocaleDateString('fr-FR')}</span>
                      ) : (
                        new Date(selectedProduct.expirationDate).toLocaleDateString('fr-FR')
                      )}
                    </p>
                  </div>
                  <div className="space-y-2">
                    <h3 className="text-sm font-medium text-zinc-500">Fournisseurs</h3>
                    <p className="text-lg font-medium text-zinc-900">{selectedProduct.nameSupplier?.length > 0 ? selectedProduct.nameSupplier.join(", ") : "N/A"}</p>
                  </div>
                </div>
                {selectedProduct.bons?.length > 0 && (
                  <div className="space-y-2">
                    <h3 className="text-sm font-medium text-zinc-500">Bons</h3>
                    <div className="flex gap-4 flex-wrap">
                      {selectedProduct.bons.map((bon, index) => (
                        <div key={index} className="flex flex-col items-center">
                          <img
                            src={`${process.env.REACT_APP_API_URL}${bon.image}`}
                            alt={`Bon ${index + 1}`}
                            className="h-16 object-contain rounded-md"
                          />
                          <p className="text-xs text-zinc-500 mt-1">
                            {bon.type} - {new Date(bon.DateBon).toLocaleDateString('fr-FR')} {bon.supplier ? `- ${bon.supplier}` : ""}
                          </p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
}
